begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1715 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:0cfae63a1a143c1604e3deb0' and md5(to_jsonb(t)::text)='3e9920fadda442440f9fbdc07ed3362b')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:0cfae63a1a143c1604e3deb0';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1100fe11a92e9703$"Objeto · Precio base · Peso\nHerramientas de manitas · 50 po · 10 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_1100fe11a92e9703$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_0e984290eec89789$[{"id":"official-table","rows":[["Herramientas de manitas","50 po","10 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_0e984290eec89789$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:0cfae63a1a143c1604e3deb0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:0f35540ad5761cc8b53de256' and md5(to_jsonb(t)::text)='dc223ad6016ceeb0d6dcd27cda5c5232')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:0f35540ad5761cc8b53de256';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b0fdb5e9b42a7c29$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b0fdb5e9b42a7c29$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:0f35540ad5761cc8b53de256';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:0fdb2edd8391f7440a662f31' and md5(to_jsonb(t)::text)='14e5b56c41af9da2ac86a3a33030f1b4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:0fdb2edd8391f7440a662f31';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_eaccb461f4441898$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer. Mientras lo lleves puesto, podrás utilizar una acción para gastar 1 de sus cargas en lanzar uno de los siguientes conjuros: • Encantar animal (CD de salvación 13). • Hablar con los animales. • Terror (CD de salvación 13), que solo puede hacer objetivo a bestias que tengan una Inteligencia de 3 o menos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_eaccb461f4441898$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:0fdb2edd8391f7440a662f31';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:11d881cebe78bd3b6034c457' and md5(to_jsonb(t)::text)='e4aebfa22af438ee6ad612458580bb95')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:11d881cebe78bd3b6034c457';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3b1106888529a711$[{"id":"flaming-toggle","kind":"bonus-action","name":"Encender o apagar la hoja","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nPronunciar la palabra de activación como acción adicional. Emite luz brillante a 40 pies y tenue otros 40 pies; se apaga al soltarla, envainarla o volver a usar la palabra como acción adicional.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":true},{"id":"flaming-hit","kind":"other","name":"Daño con la hoja encendida","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción adicional para pronunciar la palabra de activación de esta espada mágica, lo que cubrirá su hoja de llamas. Estas llamas emiten luz brillante en un radio de 12 m y luz tenue 12 m más allá. Mientras la espada esté envuelta en llamas, infligirá 2d6 de daño de fuego adicional a cualquier objetivo al que impacte. Las llamas duran hasta que utilices una acción adicional para volver a pronunciar la palabra de activación o hasta que sueltes o envaines la espada.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_3b1106888529a711$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:11d881cebe78bd3b6034c457';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1292a93cfe7a65cc643acff2' and md5(to_jsonb(t)::text)='9cbd2f2959093a595ab7b3de889bac4d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1292a93cfe7a65cc643acff2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3a00074e3ddfd597$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro forma gaseosa durante 1 hora (no requiere concentración) o hasta que pongas fin al efecto como acción adicional. El frasco de esta poción parece contener una niebla que se mueve y se derrama como si fuese agua.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3a00074e3ddfd597$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1292a93cfe7a65cc643acff2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:12dbdfe92af7a3f1f15418a0' and md5(to_jsonb(t)::text)='175378a64b3bbb2109cc2774faf26ebd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:12dbdfe92af7a3f1f15418a0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_212e7bab5e65823c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás lanzar a voluntad el conjuro salto desde él como acción adicional, pero solo podrás ser tú el objetivo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_212e7bab5e65823c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:12dbdfe92af7a3f1f15418a0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:162777d7c51d3223ce6c645e' and md5(to_jsonb(t)::text)='1aa738ffed67094ef759930dce7207dd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:162777d7c51d3223ce6c645e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_63df192432446816$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, obtendrás un bonificador de +1 a la CA. Se te considera competente con esta armadura aunque no tengas competencia con armaduras medias.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_63df192432446816$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:162777d7c51d3223ce6c645e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1690ade2e005b3d5419276d2' and md5(to_jsonb(t)::text)='96a8310501254d68e3e82fa61a77ce87')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1690ade2e005b3d5419276d2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8f83b90bcdfccf65$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de ladrón (16 po). Incluye una mochila, una bolsa con 1000 bolas de metal, 3 m de cordel, una campana, 5 velas, una palanqueta, un martillo, 10 pitones, una linterna sorda, 2 frascos de aceite, raciones para 5 días, un yesquero y una cantimplora. Además, el paquete tiene una cuerda de cáñamo de 15 m enganchada en un lado.\n\nDuración: Según su uso..","showInActions":false}]$text_8f83b90bcdfccf65$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1690ade2e005b3d5419276d2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:16bfcef27391210d1ed5263a' and md5(to_jsonb(t)::text)='c37a21e9a1e8544b97ca71ae547937e2')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:16bfcef27391210d1ed5263a';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_9fceb96e5977b7f4$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás utilizar una acción y gastar 1 de sus 3 cargas para lanzar el conjuro deseo desde él. El anillo se volverá no mágico cuando utilices la última carga.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9fceb96e5977b7f4$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:16bfcef27391210d1ed5263a';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1720e219787223e70061991c' and md5(to_jsonb(t)::text)='2a50d9f8f87ce66e3e635ba91c186dd8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1720e219787223e70061991c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_708acdbfd8530f9b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta esfera negra de 60 cm de diámetro es un agujero en el multiverso que levita en el espacio y que permanece estabilizado gracias a un campo mágico que lo rodea.\n\nLa esfera aniquila toda la materia que atraviesa y que la atraviesa. La única excepción son los artefactos, que la atravesarán intactos salvo que sean susceptibles al daño de una esfera de aniquilación. Cualquier otra cosa que toque la esfera sin ser completamente absorbida y destruida por ella sufrirá 4d10 de daño de fuerza.\n\nLa esfera permanece inmóvil hasta que alguien la controla. Si estás a 18 m o menos de una esfera no controlada, podrás utilizar una acción para realizar una prueba de Inteligencia (Conocimiento Arcano) con CD 25. Si la superas, la esfera levitará en la dirección que elijas hasta un número de metros máximo igual a 1,5 × tu modificador por Inteligencia (como mínimo 1,5 m). Si la fallas, la esfera se moverá 3 m hacia ti. Si la esfera entra en el espacio de una criatura, esta deberá superar una tirada de salvación de Destreza con CD 13 o la esfera la tocará y le infligirá 4d10 de daño de fuerza.\n\nSi tratas de controlar una esfera que se encuentre bajo el control de otra criatura, deberás realizar una prueba de Inteligencia (Conocimiento Arcano) contra la Inteligencia (Conocimiento Arcano) de la otra criatura. El vencedor se hará con el control de la esfera y podrá hacerla levitar de la manera normal.\n\nSi la esfera entra en contacto con un portal interplanar, como el que crea un conjuro portal, o un espacio extradimensional, como el que contiene un agujero portátil, tu GM determinará al azar lo que ocurrirá usando la siguiente tabla.\n\n01–50 · La esfera se destruye.\n51–85 · La esfera atraviesa el portal o entra en el espacio extradimensional.\n86–00 · Una grieta en el espacio envía a todas las criaturas y objetos que se encuentren a 54 m o menos de la esfera, incluida la esfera, a un plano de existencia aleatorio.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_708acdbfd8530f9b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1720e219787223e70061991c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:175302cfd38f05a93c9455df' and md5(to_jsonb(t)::text)='d823b5514e3aeca64bcbf7f7ea5b03d8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:175302cfd38f05a93c9455df';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e8c326586f417af7$"Objeto · Precio base · Peso\nSuministros de calígrafo · 10 po · 5 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_e8c326586f417af7$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_54f1579444fddaef$[{"id":"official-table","rows":[["Suministros de calígrafo","10 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_54f1579444fddaef$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:175302cfd38f05a93c9455df';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:17a8948e3f7bd66ba362ccbf' and md5(to_jsonb(t)::text)='d0e46f9d333194b60e83cffa9c449ca1')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:17a8948e3f7bd66ba362ccbf';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_01e90fa6b8e98336$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, tienes resistencia a un tipo de daño de entre los siguientes: contundente, cortante o perforante. Tu GM elige el tipo o lo determina al azar.\n\nMaldición. Esta armadura está maldita, circunstancia que solo se revela cuando se lanza el conjuro identificar sobre ella o te sintonizas con ella. Al sintonizarte con la armadura, sufres la maldición hasta que seas el objetivo del conjuro levantar maldición u otro efecto mágico similar. Quitarse la armadura no pone fin a la maldición. Mientras sufras la maldición, serás vulnerable a dos de los tres tipos de daño asociados con la armadura (salvo al que tienes resistencia gracias a la ella).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_01e90fa6b8e98336$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:17a8948e3f7bd66ba362ccbf';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:181be68f4b1f5b75ca241809' and md5(to_jsonb(t)::text)='2674de4cb158f73e39aa082aade71b82')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:181be68f4b1f5b75ca241809';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f0a900e527c71ac1$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +2 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador a la CA mientras lleves esta armadura. El bonificador depende de su rareza.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f0a900e527c71ac1$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:181be68f4b1f5b75ca241809';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1841b81ee7964b8aa7381ead' and md5(to_jsonb(t)::text)='eb07664a8cf38dd9e8a3dfac4ffdc879')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1841b81ee7964b8aa7381ead';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_fa8a9b68dee1c424$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta capa tiene un ligero aroma a azufre. Mientras la lleves puesta, podrás usarla para lanzar el conjuro puerta dimensional como acción. Esta propiedad de la capa no puede volver a usarse hasta el siguiente amanecer.\n\nCuando desapareces, dejas tras de ti una nube de humo y apareces en una nube de humo similar en tu destino. El humo hace que el espacio que abandonas y en el que apareces estén ligeramente oscurecidos, y se disipa al final de tu siguiente turno. Un viento suave o más fuerte dispersa el humo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fa8a9b68dee1c424$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1841b81ee7964b8aa7381ead';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1979314dd959de4052e3f286' and md5(to_jsonb(t)::text)='675e59e951550b322ccbd3887a0c7ce3')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1979314dd959de4052e3f286';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_82bc9fa4035dc2ac$"Objeto · Precio base · Peso\nCatalejo · 1000 po · 1 lb\n\nCatalejo. Los objetos que se observan a través de un catalejo se ven al doble de su tamaño real.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_82bc9fa4035dc2ac$::jsonb,true),'{features}',$text_07805aba52eb036e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Catalejo. Los objetos que se observan a través de un catalejo se ven al doble de su tamaño real.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_07805aba52eb036e$::jsonb,true),'{rules,definition,description}',$text_cccc6b99237bd431$[{"id":"official-table","rows":[["Catalejo","1000 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Catalejo. Los objetos que se observan a través de un catalejo se ven al doble de su tamaño real.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_cccc6b99237bd431$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:1979314dd959de4052e3f286';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1a642ca8b6c9c5446ce9f228' and md5(to_jsonb(t)::text)='d53eeb9fda3ce319bc6b435316410f11')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1a642ca8b6c9c5446ce9f228';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4075f39b58eb84a0$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puestas estas botas, tendrás una velocidad volando igual a tu velocidad caminando. Puedes utilizar las botas para volar durante 4 horas como máximo, ya sea de una vez o en varios vuelos más cortos, que emplearán como mínimo 1 minuto de la duración. Si estás volando cuando concluya la duración, descenderás a una velocidad de 9 m por asalto hasta que aterrices.\n\nLas botas recuperan 2 horas de vuelo por cada 12 horas que no se utilicen.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4075f39b58eb84a0$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1a642ca8b6c9c5446ce9f228';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1cc6fb29854598ed46a65f3c' and md5(to_jsonb(t)::text)='27c7e5b2cdf4a727241ed4cb7a909f74')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1cc6fb29854598ed46a65f3c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_cfaea569d2e0b0bc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, el arma ignora la resistencia al daño cortante.\n\nCuando ataques a una criatura que tenga al menos una cabeza con esta arma y el resultado de la tirada de ataque sea 20, cercenarás una de las cabezas de esa criatura. La criatura muere si no puede sobrevivir sin la cabeza perdida. Una criatura es inmune a este efecto si tiene inmunidad al daño cortante, no tiene o no necesita una cabeza, tiene acciones legendarias o tu GM decide que la criatura es demasiado grande como para que esta arma le corte la cabeza. En su lugar, una criatura así recibirá 6d8 de daño cortante adicional por el impacto.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_cfaea569d2e0b0bc$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1cc6fb29854598ed46a65f3c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1dc5037c519b0370df4df0ea' and md5(to_jsonb(t)::text)='0f731ab36982dd37b2ffd68dfcab0c44')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1dc5037c519b0370df4df0ea';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_198d9509edfb080a$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando hagas una prueba de Inteligencia (Conocimiento Arcano) para controlar una esfera de aniquilación mientras sostienes este talismán, duplicarás tu bonificador por competencia en la prueba. Además, cuando comiences tu turno con el control de una esfera de aniquilación, podrás usar una acción para hacer que levite 3 m más una cantidad de metros adicionales igual a 3 × tu modificador por Inteligencia.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_198d9509edfb080a$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1dc5037c519b0370df4df0ea';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1e8f4862e932193dfef39183' and md5(to_jsonb(t)::text)='1becbd8b4fbc8cf43bead7d13f5404ce')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1e8f4862e932193dfef39183';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8618753552b3b600$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estos pigmentos, que normalmente se encuentran en 1d4 botes dentro de una elegante caja de madera junto a un pincel (0,5 kg de peso en total), te permi- ten crear objetos tridimensionales al pintarlos en dos dimensiones. La pintura fluye de la brocha para conformar el objeto deseado a medida que te concentras en su imagen.\n\nCada bote de pintura basta para cubrir 90 m2 de una superficie, lo que te permite crear objetos inanimados o accidentes del terreno, como una puerta, un pozo, flores, árboles, celdas, habitaciones o armas, con un volumen total de 280 m3. Se tarda 10 minutos en cubrir 9 m2.\n\nCuando termines de pintar, el objeto o accidente del terreno representado se convertirá en un objeto no mágico real. Por tanto, si pintas una puerta en una pared, crearás una puerta real que pueda abrirse para acceder al otro lado. Si pintas un pozo en el suelo, crearás un pozo real y su profundidad se tendrá en cuenta en el volumen total de los objetos creados.\n\nNinguna creación de los pigmentos puede tener un valor superior a 25 po. Si pintas un objeto de mayor valor (como un diamante o un montón de oro), el objeto parecerá auténtico, pero una inspección minuciosa revelará que está hecho de pasta, hueso u otro material sin valor.\n\nSi dibujas algún tipo de energía, como fuego o un relámpago, aparecerá al completar el dibujo y se esfumará inmediatamente, sin causar daños.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8618753552b3b600$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1e8f4862e932193dfef39183';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:1f711ae53d9972c65fa8bc6d' and md5(to_jsonb(t)::text)='cfccaf7ae506cd6f8c6f84b5d0d4d09d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:1f711ae53d9972c65fa8bc6d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_30cb6bdeff7f1a7e$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras embraces este escudo, tendrás resistencia al daño de los ataques con armas a distancia.\n\nMaldición. Este escudo está maldito. Al sintonizarte con él, sufres la maldición hasta que seas el objetivo del conjuro levantar maldición u otro efecto mágico similar. Quitarse el escudo no acaba con la maldición. Cuando se realice un ataque con arma a distancia contra un objetivo a 3 m o menos de ti, la maldición hará que tú te conviertas en el objetivo en su lugar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_30cb6bdeff7f1a7e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:1f711ae53d9972c65fa8bc6d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:20072dcfe12c8dff2410a066' and md5(to_jsonb(t)::text)='a3f04471117a081e5e19189b4e73590e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:20072dcfe12c8dff2410a066';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_cf7476881ec925d8$"Objeto · Precio base · Peso\nPergamino (una hoja) · 1 pp · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_cf7476881ec925d8$::jsonb,true),'{rules,definition,description}',$text_c36033dfd652106a$[{"id":"official-table","rows":[["Pergamino (una hoja)","1 pp","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_c36033dfd652106a$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:20072dcfe12c8dff2410a066';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:204b52f3c4fd93201813054e' and md5(to_jsonb(t)::text)='75904f85816f991d9a0525998ebc2557')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:204b52f3c4fd93201813054e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_dd50717b3781ab10$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes con un ataque usando esta espada mágica, el objetivo recibirá 1d6 de daño de frío adicional. Además, mientras empuñes la espada, tendrás resistencia al daño de fuego.\n\nEn temperaturas bajo cero, la espada emite luz brillante en un radio de 3 m y luz tenue 3 m más allá.\n\nCuando desenvainas esta arma, puedes extinguir todas las llamas no mágicas que haya a 9 m o menos de ti. Esta propiedad no puede emplearse más de una vez por hora.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_dd50717b3781ab10$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:204b52f3c4fd93201813054e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:21b2968f9cb713fdc704304c' and md5(to_jsonb(t)::text)='15e53259344fd276051771b6902a6e89')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:21b2968f9cb713fdc704304c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7a591a866add0bd5$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Si caes mientras llevas puesto este anillo, descenderás 18 m por asalto y no sufrirás daño por la caída.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7a591a866add0bd5$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:21b2968f9cb713fdc704304c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:21c4865b127dd7942ad60f2f' and md5(to_jsonb(t)::text)='f344be1dcf1ff0f636cbcf01089db7ab')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:21c4865b127dd7942ad60f2f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_48d5841a3599e4a7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes este bastón, podrás utilizar una acción y gastar 1 de sus 10 cargas para lanzar los conjuros entender idiomas, hechizar persona u orden imperiosa desde él con tu CD de salvación de conjuros. El bastón puede utilizarse también como bastón mágico.\n\nSi estás empuñando el bastón y fallas una tirada de salvación contra un conjuro de encantamiento que solo te haga objetivo a ti, podrás superar la tirada fallida en su lugar. No podrás volver a usar esta propiedad hasta el siguiente amanecer. Si superas una tirada de salvación contra un conjuro de encantamiento que solo te haga objetivo a ti, con o sin la intervención del bastón, podrás utilizar tu reacción y gastar 1 carga del bastón para volver el conjuro en contra de su lanzador como si tú lo hubieras lanzado.\n\nEl bastón recupera 1d8 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en un bastón no mágico.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_48d5841a3599e4a7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:21c4865b127dd7942ad60f2f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:228455e6c8f12bf61d32bd0f' and md5(to_jsonb(t)::text)='a611f9332ec0926739c4989006e2d120')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:228455e6c8f12bf61d32bd0f';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8fc51420d0024709$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delicada prenda se ha fabricado con seda negra y tiene finas hebras plateadas entretejidas. Mientras la lleves puesta, obtendrás los siguientes beneficios: • Tienes resistencia al daño de veneno. • Tienes una velocidad trepando igual a tu velocidad caminando. • Puedes moverte hacia arriba, hacia abajo y de lado por superficies verticales, así como boca abajo por techos. Esta manera de moverse no requiere del uso de las manos, que quedan libres. • No puedes quedar atrapado en ningún tipo de red o telaraña y podrás moverte por ellas como si fueran terreno difícil. • Puedes usar una acción para lanzar el conjuro telaraña (CD de salvación 13). La telaraña creada por este conjuro tiene el doble del tamaño normal. Una vez utilizada, esta propiedad de la capa no puede volver a usarse hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8fc51420d0024709$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:228455e6c8f12bf61d32bd0f';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2332efbe842bef596b4af269' and md5(to_jsonb(t)::text)='07b0bc3c0daa2e7d6fe059559b1b96af')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2332efbe842bef596b4af269';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d20682e3808f6a0$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2332efbe842bef596b4af269';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2332f606e84baed04abe564c' and md5(to_jsonb(t)::text)='022d8fc28d230c00310bc86285cc9c0d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2332f606e84baed04abe564c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b40b5f9186ea5148$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes un bonificador a las tiradas de ataque y de daño que hagas con esta unidad de munición mágica. El bonificador depende de la rareza de la munición. Una vez que impacte en un objetivo, la munición dejará de ser mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b40b5f9186ea5148$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2332f606e84baed04abe564c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:234d31692db9f12b1e42dbb2' and md5(to_jsonb(t)::text)='5ad5aa6bc1fbadfe64265d976f7cc835')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:234d31692db9f12b1e42dbb2';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_2467095af0cbf025$"Objeto · Precio base · Peso\nSuministros de cervecero · 20 po · 9 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_2467095af0cbf025$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_088f854cd8c99670$[{"id":"official-table","rows":[["Suministros de cervecero","20 po","9 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_088f854cd8c99670$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:234d31692db9f12b1e42dbb2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:23abf7f292bc7bc0f40d9f43' and md5(to_jsonb(t)::text)='16ae7f268a3777045204670a2a5100e4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:23abf7f292bc7bc0f40d9f43';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_977e20479b0599c5$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este cubo mide aproximadamente 2,5 cm de lado. Cada cara tiene un signo específico que puede pulsarse. El cubo comienza con 36 cargas y recupera 1d20 cargas empleadas cada día, al amanecer.\n\nPuedes usar una acción para pulsar una de las caras del cubo y gastar una cantidad de cargas que dependerá de la cara en cuestión, tal y como se muestra en la tabla “Caras del cubo de fuerza”. Cada cara tiene un efecto diferente. Si al cubo no le quedan suficientes cargas, no ocurrirá nada. En caso contrario, surgirá una barrera de fuerza invisible que formará un cubo de 4,5 m de lado. La barrera se centra en ti, se mueve contigo y dura 1 minuto, hasta que emplees una acción para pulsar la sexta cara del cubo o hasta que el cubo se quede sin cargas. Puedes cambiar el efecto de la barrera si pulsas otra cara del cubo y gastas la cantidad necesaria de cargas, lo que reiniciará la duración.\n\nSi tu movimiento hace que la barrera entre en contacto con un objeto sólido que no pueda atravesar el cubo, no serás capaz de acercarte más a ese objeto hasta que la barrera deje de existir. Caras del cubo de fuerza\n\n1 · 1 · Los gases, el viento y la niebla no pueden atravesar la barrera.\n2 · 2 · La materia inerte no puede atravesar la barrera. Los muros, suelos y techos pueden atravesarla a tu discreción.\n3 · 3 · La materia viva no puede atravesar la barrera.\n4 · 4 · Los efectos de conjuros no pueden atravesar la barrera.\n5 · 5 · Nada puede atravesar la barrera. Los muros, suelos y techos pueden atravesarla a tu discreción.\n6 · 0 · La barrera se desactiva.\n\nEl cubo pierde cargas cuando la barrera es el objetivo de determinados conjuros o entra en contacto con los efectos de ciertos conjuros u objetos mágicos, tal y como se muestra en la tabla siguiente.\n\nCuerno de estallido · 1d10\nDesintegrar · 1d12\nMuro de fuego · 1d4\nPasamuros · 1d6\nRociada prismática · 1d20\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_977e20479b0599c5$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:23abf7f292bc7bc0f40d9f43';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:23f23e21a5e68c1fae048f09' and md5(to_jsonb(t)::text)='837d80a3dcb538e06188f12985863657')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:23f23e21a5e68c1fae048f09';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a48d0c039253fa2$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:23f23e21a5e68c1fae048f09';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:240e4ce5f914087a513da6a2' and md5(to_jsonb(t)::text)='192b6b2f6a10eda8d3f6acb250102d5e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:240e4ce5f914087a513da6a2';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f3ae9b4fecfd8020$"Objeto · Precio base · Peso\nCantimplora · 2 pp · 5 lb (llena)\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f3ae9b4fecfd8020$::jsonb,true),'{rules,definition,description}',$text_0ad7a883d022e3a3$[{"id":"official-table","rows":[["Cantimplora","2 pp","5 lb (llena)"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_0ad7a883d022e3a3$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:240e4ce5f914087a513da6a2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:24a89eb8efb8617f0eecf7e4' and md5(to_jsonb(t)::text)='05195940aa3372f8927511413dbe33c4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:24a89eb8efb8617f0eecf7e4';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_6f7347b1b4da5195$[{"id":"withering-hit","kind":"other","name":"Marchitamiento","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"2d10"}],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"Este bastón tiene 3 cargas y recupera 1d3 cargas empleadas cada día, al amanecer.\n\nEl bastón se puede usar a modo de bastón mágico. Si impactas con él, causa daño como un bastón normal y puedes gastar 1 carga para infligir 2d10 de daño necrótico adicional al objetivo. Además, el objetivo deberá superar una tirada de salvación de Constitución con CD 15 o tendrá desventaja durante 1 hora en cualquier prueba de característica o tirada de salvación que utilice la Fuerza o la Constitución.\n\nDuración: 1 hora para la desventaja; el daño es inmediato..\n\nCoste: 1 cargas.","showInActions":false}]$text_6f7347b1b4da5195$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:24a89eb8efb8617f0eecf7e4';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:250884d74945e41176af6df1' and md5(to_jsonb(t)::text)='c8635a2acb8480e017771482d643d174')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:250884d74945e41176af6df1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b40b5f9186ea5148$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes un bonificador a las tiradas de ataque y de daño que hagas con esta unidad de munición mágica. El bonificador depende de la rareza de la munición. Una vez que impacte en un objetivo, la munición dejará de ser mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b40b5f9186ea5148$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:250884d74945e41176af6df1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2576abf7d0b4aa35a244426d' and md5(to_jsonb(t)::text)='0cf01cda673238cf688b3cb858bb4861')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2576abf7d0b4aa35a244426d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2576abf7d0b4aa35a244426d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:25c626a208ba4a32f000c0d0' and md5(to_jsonb(t)::text)='d45c776c34b2abb19e15a4f003aad46f')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:25c626a208ba4a32f000c0d0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_29a45bdffabc85d9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro clarividencia. En este líquido amarillento flota un globo ocular, pero desaparece en cuanto se abre la poción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_29a45bdffabc85d9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:25c626a208ba4a32f000c0d0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:25d11d7b5a7b5c94a5f9c0c8' and md5(to_jsonb(t)::text)='41f6c9a8e9ea67086bb36e582f8aea40')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:25d11d7b5a7b5c94a5f9c0c8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7b31b792807934b9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás resistencia a un tipo de daño. La gema incrustada en el anillo, que tu GM elige o determina al azar, indica el tipo de daño.\n\n1 · Ácido · Perla\n2 · Frío · Turmalina\n3 · Fuego · Granate\n4 · Fuerza · Zafiro\n5 · Necrótico · Azabache\n6 · Psíquico · Jade\n7 · Radiante · Topacio\n8 · Relámpago · Citrino\n9 · Trueno · Espinela\n10 · Veneno · Amatista\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7b31b792807934b9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:25d11d7b5a7b5c94a5f9c0c8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:27449e1bed6d4f91099fb4e4' and md5(to_jsonb(t)::text)='63c55b8ca1c66149cd246d2ff2ead561')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:27449e1bed6d4f91099fb4e4';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_098e651649ff7d4d$[{"id":"mundane-assisted-use","kind":"other","name":"Jugar con competencia","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado.\n\nDuración: Según su uso..","showInActions":false}]$text_098e651649ff7d4d$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:27449e1bed6d4f91099fb4e4';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d' and md5(to_jsonb(t)::text)='f259fcea9f112324736356ae467666d8')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:283d43a7fbb28f2f5d081a4d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_9e343969c674a850$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 de sus cargas y elegir un objetivo a 36 m o menos de ti. El objetivo puede ser una criatura, un objeto o un punto en el espacio. Tira 1d100 y consulta la tabla que aparece a continuación para descubrir lo que ocurrirá.\n\nSi el efecto hace que lances un conjuro con la varita, la CD de salvación será 15. Si el conjuro tiene normalmente un alcance expresado en metros, su alcance pasará a ser de 36 m (si no lo era ya).\n\nSi un efecto cubre un área, deberás centrar el conjuro en el objetivo e incluirlo en su interior. Si un efecto tiene varios objetivos posibles, tu GM determinará al azar cuáles se verán afectados.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en polvo y se destruye.\n\n01–05 · Lanzas ralentizar.\n06–10 · Lanzas fuego feérico.\n11–15 · Crees que algo asombroso acaba de ocurrir, por lo que te quedas aturdido hasta el principio de tu siguiente turno.\n16–20 · Lanzas ráfaga de viento.\n21–25 · Lanzas detectar pensamientos sobre el objetivo que elijas. Si no has hecho objetivo a una criatura, en vez de eso, recibirás 1d6 de daño psíquico.\n26–30 · Lanzas nube apestosa.\n31–33 · Una lluvia intensa cae en un radio de 18 m centrado en el objetivo. La zona se vuelve ligeramente oscura. La lluvia cae hasta el principio de tu siguiente turno.\n34–36 · Un animal aparece en el espacio sin ocupar más cercano al objetivo. El animal no se encuentra bajo tu control y actúa con normalidad. Tira 1d100 para determinar qué animal aparece. Si el resultado es 01-25, aparecerá un rinoceronte; si es 26-50, aparecerá un elefante, y con 51-100, aparecerá una rata.\n37–46 · Lanzas relámpago.\n47–49 · Una nube de 600 mariposas de gran tamaño cubre un radio de 9 m centrado en el objetivo. La zona se vuelve muy oscura. Las mariposas permanecen durante 10 minutos.\n50–53 · Aumentas el tamaño del objetivo como si hubieras lanzado agrandar/reducir. Si el objetivo no puede verse afectado por ese conjuro o si no has hecho objetivo a una criatura, tú te convertirás en el objetivo.\n54–58 · Lanzas oscuridad.\n59–62 · La hierba crece en el suelo en un radio de 18 m centrado en el objetivo. Si ya había hierba allí, crecerá hasta diez veces su tamaño normal y tendrá ese tamaño durante 1 minuto.\n63–65 · Un objeto a elección de tu GM desaparece en el Plano Etéreo. El objeto no puede medir más de 3 m en ninguna dimensión, debe encontrarse a 36 m o menos del objetivo y nadie puede vestirlo o llevarlo.\n66–69 · Encoges como si hubieras lanzado agrandar/reducir sobre ti.\n70–79 · Lanzas bola de fuego.\n80–84 · Lanzas invisibilidad sobre ti.\n85–87 · Crecen hojas en el objetivo. Si eliges un punto en el espacio como objetivo, las hojas brotan de la criatura más cercana a ese punto. Salvo que se arranquen, las hojas se volverán marrones y caerán tras 24 horas.\n88–90 · Una ráfaga de 1d4 × 10 gemas, cada una con un valor de 1 po, sale disparada de la punta de la varita en una línea de 9 m de largo y 1,5 m de ancho. Cada gema hace 1 de daño contundente y el total de daño de las gemas se divide a partes iguales entre todas las criaturas situadas en la línea.\n91–95 · Una explosión de luz resplandeciente y colorida se extiende desde ti en un radio de 9 m. Todas las criaturas que puedan ver en el área y tú deberéis superar una tirada de salvación de Constitución con CD 15 o quedaréis cegados durante 1 minuto. Una criatura puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n96–97 · La piel del objetivo se vuelve azul brillante durante 1d10 días. Si has elegido un punto en el espacio como objetivo, la criatura más cercana a ese punto será quien sufra el efecto.\n98–00 · Si tu objetivo es una criatura, deberá hacer una tirada de salvación de Constitución con CD 15. Si no has hecho objetivo a una criatura, tú te convertirás en el objetivo y deberás hacer la tirada de salvación. Si la falla por 5 o más, el objetivo quedará petrificado instantáneamente. Si la falla con otro resultado, el objetivo quedará apresado y comenzará a convertirse en piedra. Mientras el objetivo esté apresado de esta forma, deberá repetir la tirada de salvación al final de su siguiente turno; quedará petrificado si la falla o se librará del efecto si la supera. La petrificación dura hasta que el objetivo sea liberado mediante un conjuro restablecimiento mayor u otro efecto mágico similar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9e343969c674a850$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:283d43a7fbb28f2f5d081a4d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8' and md5(to_jsonb(t)::text)='227eb789df20d856d19828d7e6f4faea')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:285015c1f803ed9cd52a94c8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_1d722e423b49351b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para conjurar un delgado rayo azul que serpenteará desde la punta de la varita hacia una criatura que puedas ver a 18 m o menos de ti. El objetivo deberá superar una tirada de salvación de Constitución con CD 15 o quedará paralizado durante 1 minuto. Podrá repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_1d722e423b49351b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:285015c1f803ed9cd52a94c8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:288b0e63563a7d6ecda0925b' and md5(to_jsonb(t)::text)='532ae30b7d78fe0b13ddd44121b0a14c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:288b0e63563a7d6ecda0925b';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_e1f13f389bea68e5$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás resistencia a un tipo de daño durante 1 hora. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_e1f13f389bea68e5$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:288b0e63563a7d6ecda0925b';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:28901ef2614cdb26e4f09af0' and md5(to_jsonb(t)::text)='26b01e8c384ee8594004aa9bceb016fd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:28901ef2614cdb26e4f09af0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_6831ba56f10b63d2$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La próxima vez que veas a una criatura en los 10 minutos posteriores a beber este filtro, quedarás hechizado por ella durante 1 hora. Si la criatura es de una especie y género que normalmente te atraigan, la considerarás tu amor verdadero mientras permanezcas hechizado. El líquido efervescente y de tonalidad rosa de este brebaje contiene una burbuja, fácil de pasar por alto, con forma de corazón.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6831ba56f10b63d2$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:28901ef2614cdb26e4f09af0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:29b91b0b62ab8ab131ddf0b1' and md5(to_jsonb(t)::text)='6effdef8c98581c967f958f0072cebe6')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:29b91b0b62ab8ab131ddf0b1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_657c259537dee184$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa con la capucha puesta, podrás respirar bajo el agua y tendrás una velocidad nadando de 18 m. Ponerte o quitarte la capucha requiere una acción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_657c259537dee184$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:29b91b0b62ab8ab131ddf0b1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2b27121f4f6b49d06be83a0b' and md5(to_jsonb(t)::text)='bf0e03404a95ec27eff61a0db7deabc5')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2b27121f4f6b49d06be83a0b';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2b27121f4f6b49d06be83a0b';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2b9317ec14536ced5520b06e' and md5(to_jsonb(t)::text)='86bad7c9d971a25528084d4344bd36df')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2b9317ec14536ced5520b06e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_b86cf8ddf5843e97$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 50 cargas para utilizar las propiedades que se describen a continuación. Recupera 4d6 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 20, el bastón recupera 1d12 + 1 cargas.\n\nAbsorción de conjuros. Mientras empuñes el bastón, tendrás ventaja en las tiradas de salvación contra conjuros. Además, puedes usar tu reacción cuando otra criatura lance un conjuro que solo te haga objetivo a ti. Si lo haces, el bastón absorberá la magia del conjuro, cancelará su efecto y obtendrá una cantidad de cargas igual al nivel del conjuro absorbido. No obstante, si esto hace que la cantidad total de cargas del bastón supere las 50, el bastón explotará como si hubieses activado su golpe vengador (consulta más adelante).\n\nConjuros. Mientras empuñes el bastón, puedes usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y aptitud mágica: abrir (2 cargas), bola de fuego (versión de nivel 7, 7 cargas), conjurar elemental (7 cargas), desplazamiento entre planos (7 cargas), disipar magia (3 cargas), esfera de llamas (2 cargas), invisibilidad (2 cargas), muro de fuego (4 cargas), pasamuros (5 cargas), relámpago (versión de nivel 7, 7 cargas), telaraña (2 cargas), telequinesis (5 cargas) o tormenta de hielo (4 cargas).\n\nTambién puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin gastar ninguna carga: agrandar/reducir, cerradura arcana, detectar magia, luz, mano de mago o protección contra el bien y el mal.\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 50 cargas para utilizar las propiedades que se describen a continuación. Recupera 4d6 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 20, el bastón recupera 1d12 + 1 cargas.\n\nAbsorción de conjuros. Mientras empuñes el bastón, tendrás ventaja en las tiradas de salvación contra conjuros. Además, puedes usar tu reacción cuando otra criatura lance un conjuro que solo te haga objetivo a ti. Si lo haces, el bastón absorberá la magia del conjuro, cancelará su efecto y obtendrá una cantidad de cargas igual al nivel del conjuro absorbido. No obstante, si esto hace que la cantidad total de cargas del bastón supere las 50, el bastón explotará como si hubieses activado su golpe vengador (consulta más adelante).\n\nConjuros. Mientras empuñes el bastón, puedes usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y aptitud mágica: abrir (2 cargas), bola de fuego (versión de nivel 7, 7 cargas), conjurar elemental (7 cargas), desplazamiento entre planos (7 cargas), disipar magia (3 cargas), esfera de llamas (2 cargas), invisibilidad (2 cargas), muro de fuego (4 cargas), pasamuros (5 cargas), relámpago (versión de nivel 7, 7 cargas), telaraña (2 cargas), telequinesis (5 cargas) o tormenta de hielo (4 cargas).\n\nTambién puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin gastar ninguna carga: agrandar/reducir, cerradura arcana, detectar magia, luz, mano de mago o protección contra el bien y el mal.\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b86cf8ddf5843e97$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2b9317ec14536ced5520b06e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2bc2a95f6395e248236a47ab' and md5(to_jsonb(t)::text)='e822e6348eedfa396878c3c3687122bf')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2bc2a95f6395e248236a47ab';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d20682e3808f6a0$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2bc2a95f6395e248236a47ab';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2bda57073d4de65a9fc99b84' and md5(to_jsonb(t)::text)='814163dc70895a3c29432c5825dc9668')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2bda57073d4de65a9fc99b84';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_2268b2509e814df7$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este amuleto, permanecerás oculto ante la magia de adivinación. No podrás ser objetivo de ningún efecto mágico de ese tipo ni podrán percibirte mediante sensores mágicos de escudriñamiento.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2268b2509e814df7$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2bda57073d4de65a9fc99b84';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2ce971dab6d5fa7c121bc193' and md5(to_jsonb(t)::text)='42052a04181c9a00b83fcb78991fe92b')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2ce971dab6d5fa7c121bc193';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_aaf89e7b6a02353d$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro acelerar durante 1 minuto (no requiere concentración). El líquido amarillo de este brebaje tiene vetas negras y forma remolinos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_aaf89e7b6a02353d$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2ce971dab6d5fa7c121bc193';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2d00d208f92c4357d88f466e' and md5(to_jsonb(t)::text)='cedba234f2300dd79f0257bd3403cc6a')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2d00d208f92c4357d88f466e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_fc57461b72b10b78$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación de la alfombra y hacer que levite y vuele. Se moverá según las indicaciones verbales que le des, siempre y cuando estés a 9 m o menos de distancia de ella.\n\nExisten cuatro tamaños de alfombra voladora. TU GM elige el tamaño o lo determina al azar.\n\n01–20 90 cm × 1,5 m ·  · 100 kg · 24 m\n21–55 1,2 m × 1,8 m ·  · 200 kg · 18 m\n56–80 1,5 m × 2,1 m ·  · 300 kg · 12 m\n81–100 1,8 m × 2,7 m ·  · 400 kg · 9 m\n\nLa alfombra puede transportar hasta el doble del peso mostrado en la tabla, pero vuela a la mitad de su velocidad si transporta un peso superior a su capacidad normal.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fc57461b72b10b78$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:2d00d208f92c4357d88f466e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:2d32f4a1dfeb0a52c48095f1' and md5(to_jsonb(t)::text)='9b715a37639bbb078e3f4a7e2708ea16')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:2d32f4a1dfeb0a52c48095f1';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_3b91126f195b264e$"Objeto · Precio base · Peso\nÁcido (vial) · 25 po · 1 lb\n\nÁcido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_3b91126f195b264e$::jsonb,true),'{features}',$text_03a33af9cb8863f0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Ácido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_03a33af9cb8863f0$::jsonb,true),'{rules,definition,description}',$text_a405f1f3fe336dd6$[{"id":"official-table","rows":[["Ácido (vial)","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Ácido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_a405f1f3fe336dd6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:2d32f4a1dfeb0a52c48095f1';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 11 as batch,49 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;